#include <stdio.h>

static int counter = 0;

int add(int a, int b)
{
  int sum = a + b;
  counter++;
  return sum;
}

int sub(int a, int b)
{
  int diff = a - b;
  counter++;
  return diff;
}

int main(void)
{
  printf("%d\n", add(1, 2));
  printf("%d\n", sub(3, 1));
  return 0;
}

